function placeVignetteUi(){const host=$('#vignette-ui');if(!host||!canvas)return;const l=activeVignette();if(!l){host.hidden=true;host.innerHTML='';return;}const drag=vignetteDrag,handles=vignetteHandles(l),dragged=drag?Math.min(drag.index,handles.length-1):-1;host.hidden=false;host.innerHTML=handles.map((h,i)=>`<div class="gap-hit vignette-gap ${h.axis} ${h.key}${h.card>0?' quiet':''}${i===dragged?' dragging':''}" data-vignette-gap="${h.key}" data-axis="${h.axis}" style="${boxStyle(vignetteHitBox(h))}" title="${vignetteGapLabel(l,h.key)}"><i class="gap-tick"></i><b class="gap-badge">${mmLabel(vignetteGap(l,h.key))}</b></div>`).join('');}
