function syncColorPop(apply=true){if(!colorPop)return;const {h,s,v}=colorPop.hsv,hex=hsvToHex(h,s,v),pop=$('#color-pop');$('#color-sv').style.background=`linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,hsl(${h} 100% 50%))`;$('#color-sv-knob').style.left=(s*100)+'%';$('#color-sv-knob').style.top=((1-v)*100)+'%';$('#color-hue-knob').style.left=(h/360*100)+'%';$('#color-hue-knob').style.top='50%';$('#color-alpha').style.backgroundImage=`linear-gradient(90deg,transparent,${hex}),linear-gradient(45deg,#e6e4ea 25%,transparent 25%),linear-gradient(-45deg,#e6e4ea 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e6e4ea 75%),linear-gradient(-45deg,transparent 75%,#e6e4ea 75%)`;$('#color-alpha-knob').style.left=colorPop.opacity+'%';$('#color-alpha-knob').style.top='50%';$('#color-hex').value=hex.toUpperCase();$('#color-alpha-input').value=Math.round(colorPop.opacity);$('#color-alpha').hidden=colorPop.key==='page.background';$('#color-alpha-input').hidden=$('#color-alpha').hidden;$('#color-alpha-input').nextElementSibling.hidden=$('#color-alpha').hidden;if(apply)paintColor(hex,colorPop.key==='page.background'?null:colorPop.opacity);let rect=colorPop.anchor.getBoundingClientRect();if(rect.width<2){$('.right-panel').classList.add('mobile-open');rect=colorPop.anchor.getBoundingClientRect();}pop.hidden=false;const left=Math.max(8,Math.min(rect.width?rect.left:innerWidth-pop.offsetWidth-16,innerWidth-pop.offsetWidth-8));const below=rect.bottom+8;pop.style.left=left+'px';pop.style.top=Math.max(8,below+pop.offsetHeight>innerHeight?Math.max(8,rect.top-pop.offsetHeight-8):below)+'px';}
function openColor(button){if(colorPop?.anchor===button)return closeColor(false);if(colorPop){const changed=colorPop.moved&&JSON.stringify(doc)!==JSON.stringify(colorPop.start);if(changed){rememberColor(hsvToHex(colorPop.hsv.h,colorPop.hsv.s,colorPop.hsv.v));history.push(colorPop.start);if(history.length>60)history.shift();future=[];markDirty();}colorPop=null;}colorPop={key:button.dataset.colorKey,anchor:button,hsv:hexToHsv(button.dataset.colorValue||'#333333'),opacity:colorOpacity(button.dataset.colorKey),start:clone(doc),moved:false};$('#color-swatches').innerHTML=swatchColors.map(c=>`<button type="button" data-swatch="${c}" style="--swatch:${c}" aria-label="${c}"></button>`).join('');renderRecentColors();syncColorPop(false);}
