function markIcon(name){const paths={left:'M4 6h16M4 12h10M4 18h16',center:'M4 6h16M7 12h10M4 18h16',right:'M4 6h16M10 12h10M4 18h16',justify:'M4 6h16M4 12h16M4 18h16',solid:'M4 12h16',dashed:'M4 12h3.5M10.2 12h3.5M16.5 12h3.5',dotted:'M5 12h.1M9 12h.1M13 12h.1M17 12h.1M21 12h.1',centerStroke:'M6 6h12v12H6z',outside:'M4 4h16v16H4zM7 7h10v10H7z'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`;}
