function textAlignBar(value,prefix=''){const icons={left:'<svg viewBox="0 0 24 24"><path d="M4 7h16M4 12h10M4 17h16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',center:'<svg viewBox="0 0 24 24"><path d="M4 7h16M7 12h10M4 17h16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',right:'<svg viewBox="0 0 24 24"><path d="M4 7h16M10 12h10M4 17h16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',justify:'<svg viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>'};return segments(prefix+'align',value||'left',[['left','Слева',icons.left],['center','По центру',icons.center],['right','Справа',icons.right],['justify','По ширине',icons.justify]]);}
