function submitTextStyleMenu(name){if(!textStyleMenu)return;const mode=textStyleMenu.mode,layer=allLayers().find(l=>l.id===textStyleMenu.layerId),current=textStyle(layer),clean=name.trim().slice(0,60);if(!clean)return notify('Укажите название стиля',true);if(mode==='create'&&(doc.textStyles||[]).length>=50)return notify('В макете уже 50 стилей',true);if(!layer)return closeTextStyleMenu();closeTextStyleMenu();commit(()=>{if(mode==='create'){const style={id:'style-'+uid(),name:clean};for(const key of textStyleKeys)style[key]=layer[key]??(key==='lineHeight'?1.25:key==='letterSpacing'?0:['bold','italic','underline','strike'].includes(key)?false:'');doc.textStyles.push(style);layer.styleId=style.id;syncTextStyle(style);}else if(current)current.name=clean;});}
