function findCanvasObject(id){const active=canvas.getActiveObject();if(active instanceof fabric.ActiveSelection){const inner=active.getObjects().find(o=>o.masterId===id);if(inner)return inner;}return canvas.getObjects().find(o=>o.masterId===id)||null;}
