function snapTargets(skip){const w=pageWidth(),h=pageHeight(),settings=section().cover?(section().safety||{}):(doc.safety||{}),safe=Number(settings.safe)||0,bleed=Number(settings.bleed)||0,xs=[],ys=[];const addX=(pos,kind,bounds)=>{if(pos>=-2&&pos<=2*w+2)xs.push({pos,kind,bounds,axis:'x'});};const addY=(pos,kind,bounds)=>{if(pos>=-2&&pos<=h+2)ys.push({pos,kind,bounds,axis:'y'});};for(let side=0;side<2;side++){const x=side*w;addX(x,'trim');addX(x+w,'trim');addX(x+w/2,'center');if(bleed>0){addX(x+bleed,'bleed');addX(x+w-bleed,'bleed');}const inset=bleed+safe;if(safe>0&&inset<Math.min(w,h)/2){addX(x+inset,'safe');addX(x+w-inset,'safe');}}addY(0,'trim');addY(h,'trim');addY(h/2,'center');if(bleed>0){addY(bleed,'bleed');addY(h-bleed,'bleed');}const inset=bleed+safe;if(safe>0&&inset<Math.min(w,h)/2){addY(inset,'safe');addY(h-inset,'safe');}if(section().cover){const spine=Number(settings.spine)||0,gap=Number(settings.gap)||0,center=w;if(spine>0){addX(center-spine/2,'spine');addX(center+spine/2,'spine');}if(gap>0){addX(center-spine/2-gap,'gap');addX(center+spine/2+gap,'gap');}}for(const obj of canvas.getObjects()){if(!obj.masterId||skip.has(obj.masterId))continue;const b=sceneBounds(obj);addX(b.left,'object',b);addX(b.cx,'object',b);addX(b.right,'object',b);addY(b.top,'object',b);addY(b.cy,'object',b);addY(b.bottom,'object',b);}return {xs,ys};}
