function bestShift(edges,lines,threshold){let best=null;for(const edge of edges)for(const line of lines){const delta=line.pos-edge,abs=Math.abs(delta);if(abs>threshold)continue;const score=abs+(snapRank[line.kind]??9)*0.0001;if(!best||score<best.score)best={delta,score};}return best?best.delta:0;}
function guideSpan(axis,line,bounds){const w=pageWidth(),h=pageHeight();if(line.kind==='object'&&line.bounds){const other=line.bounds;if(axis==='x')return {from:Math.min(bounds.top,other.top),to:Math.max(bounds.bottom,other.bottom)};return {from:Math.min(bounds.left,other.left),to:Math.max(bounds.right,other.right)};}if(axis==='x')return {from:0,to:h};const start=clamp(Math.floor(Math.min(bounds.left,bounds.right)/w),0,1),end=clamp(Math.floor(Math.max(bounds.left,bounds.right-0.01)/w),0,1);return {from:start*w,to:(Math.max(start,end)+1)*w};}
function renderGuides(){const host=$('#guide-ui');if(!host)return;if(!snapMarks.length){host.hidden=true;host.innerHTML='';return;}const zoom=canvas.getZoom()||1,pad=12/zoom;host.hidden=false;host.innerHTML=snapMarks.map(mark=>{const from=mark.from-pad,to=mark.to+pad;if(mark.axis==='x'){const a=sceneToHost(mark.pos,from),b=sceneToHost(mark.pos,to),top=Math.min(a.y,b.y);return `<i class="guide-line v" style="left:${Math.round(a.x)}px;top:${Math.round(top)}px;height:${Math.max(1,Math.round(Math.abs(b.y-a.y)))}px"></i>`;}const a=sceneToHost(from,mark.pos),b=sceneToHost(to,mark.pos),left=Math.min(a.x,b.x);return `<i class="guide-line h" style="left:${Math.round(left)}px;top:${Math.round(a.y)}px;width:${Math.max(1,Math.round(Math.abs(b.x-a.x)))}px"></i>`;}).join('');}
