function paintMatch(bounds,xs,ys){const eps=0.2,marks=[];const take=(axis,lines,edges)=>{for(const line of lines){if(!edges.some(edge=>Math.abs(edge-line.pos)<=eps))continue;const span=guideSpan(axis,line,bounds),key=axis+':'+Math.round(line.pos*10),found=marks.find(m=>m.key===key);if(found){found.from=Math.min(found.from,span.from);found.to=Math.max(found.to,span.to);}else marks.push({key,axis,pos:line.pos,from:span.from,to:span.to});}};take('x',xs,[bounds.left,bounds.cx,bounds.right]);take('y',ys,[bounds.top,bounds.cy,bounds.bottom]);snapMarks=marks;renderGuides();}
function hideDragUi(){const ui=$('#collage-ui');if(ui)ui.hidden=true;const space=$('#space-ui');if(space)space.hidden=true;}
function snapMove(target){if(!target)return;const bounds=sceneBounds(target),lines=snapTargets(movingIds(target)),threshold=6/(canvas.getZoom()||1);const dx=bestShift([bounds.left,bounds.cx,bounds.right],lines.xs,threshold),dy=bestShift([bounds.top,bounds.cy,bounds.bottom],lines.ys,threshold);if(dx||dy){target.set({left:target.left+dx,top:target.top+dy});target.setCoords();}paintMatch(dx||dy?sceneBounds(target):bounds,lines.xs,lines.ys);}
function nearlyStraight(obj){const angle=Math.abs(obj?.angle||0)%180;return angle<0.8||Math.abs(angle-180)<0.8;}
function snapResize(target,corner,mode){if(!target||!corner||corner==='mtr'||!nearlyStraight(target)){clearGuides();return;}const moveL=corner==='ml'||corner==='tl'||corner==='bl',moveR=corner==='mr'||corner==='tr'||corner==='br',moveT=corner==='mt'||corner==='tl'||corner==='tr',moveB=corner==='mb'||corner==='bl'||corner==='br';if(!moveL&&!moveR&&!moveT&&!moveB){clearGuides();return;}const bounds=sceneBounds(target),lines=snapTargets(movingIds(target)),threshold=6/(canvas.getZoom()||1);let left=bounds.left,right=bounds.right,top=bounds.top,bottom=bounds.bottom,dx=0,dy=0;if(moveL&&!moveR){dx=bestShift([left],lines.xs,threshold);left+=dx;}else if(moveR&&!moveL){dx=bestShift([right],lines.xs,threshold);right+=dx;}if(moveT&&!moveB){dy=bestShift([top],lines.ys,threshold);top+=dy;}else if(moveB&&!moveT){dy=bestShift([bottom],lines.ys,threshold);bottom+=dy;}if(right-left<1){left=bounds.left;right=bounds.right;dx=0;}if(bottom-top<1){top=bounds.top;bottom=bounds.bottom;dy=0;}if(dx||dy){const patch={};if(dx){const newW=right-left;if(mode==='resize')patch.width=Math.max(newW/Math.abs(target.scaleX||1),1);else patch.scaleX=(target.scaleX||1)*(newW/(bounds.width||1));patch.left=target.left+((left+right)/2-bounds.cx);}if(dy){const newH=bottom-top;if(mode==='resize')patch.height=Math.max(newH/Math.abs(target.scaleY||1),1);else patch.scaleY=(target.scaleY||1)*(newH/(bounds.height||1));patch.top=target.top+((top+bottom)/2-bounds.cy);}target.set(patch);target.setCoords();target.dirty=true;}paintMatch(sceneBounds(target),lines.xs,lines.ys);}
