canvas.on('object:resizing',opt=>{hideVignetteUi();onSnap(opt,'resize');});
function crossMid(a0,a1,b0,b1,fallback){const from=Math.max(a0,b0),to=Math.min(a1,b1);return to>from?(from+to)/2:fallback;}
function layerSceneBox(layer){const obj=findCanvasObject(layer.id);if(!obj)return null;const angle=Math.abs(layer.angle||obj.angle||0)%180;if(angle>0.8&&Math.abs(angle-180)>0.8){const b=sceneBounds(obj);b.layer=layer;b.obj=obj;return b;}const x=(obj.side||0)*pageWidth()+layer.box.x,y=layer.box.y;return {left:x,top:y,right:x+layer.box.w,bottom:y+layer.box.h,width:layer.box.w,height:layer.box.h,cx:x+layer.box.w/2,cy:y+layer.box.h/2,layer,obj};}
function relateBoxes(a,b,forceAxis){const gapX=Math.max(a.left,b.left)-Math.min(a.right,b.right),gapY=Math.max(a.top,b.top)-Math.min(a.bottom,b.bottom),axis=forceAxis||(gapX>=0&&gapY<0?'x':gapY>=0&&gapX<0?'y':Math.abs(a.cx-b.cx)>=Math.abs(a.cy-b.cy)?'x':'y');if(axis==='x'){const left=a.cx<=b.cx?a:b,right=left===a?b:a;return {axis,gap:right.left-left.right,anchor:left,mover:right,mid:crossMid(left.top,left.bottom,right.top,right.bottom,(left.cy+right.cy)/2)};}const top=a.cy<=b.cy?a:b,bottom=top===a?b:a;return {axis,gap:bottom.top-top.bottom,anchor:top,mover:bottom,mid:crossMid(top.left,top.right,bottom.left,bottom.right,(top.cx+bottom.cx)/2)};}
function objectPair(forceAxis){if(preview||tool!=='select'||selected.length!==2)return null;const boxes=chosen().filter(l=>!l.hidden).map(layerSceneBox).filter(Boolean);if(boxes.length!==2)return null;return relateBoxes(boxes[0],boxes[1],forceAxis);}
function spaceScreen(rel){const zoom=canvas.getZoom()||1;let cx,cy;if(rel.axis==='x'){cx=rel.anchor.right+rel.gap/2;cy=rel.mid;}else{cx=rel.mid;cy=rel.anchor.bottom+rel.gap/2;}const p=sceneToHost(cx,cy),along=Math.max(20,Math.min(32,Math.abs(rel.gap)*zoom||20)),cross=40;if(rel.axis==='x')return {left:p.x-along/2,top:p.y-cross/2,width:along,height:cross};return {left:p.x-cross/2,top:p.y-along/2,width:cross,height:along};}
