function placeSpaceUi(){const host=$('#space-ui');if(!host)return;if(spaceDrag){host.hidden=false;moveSpaceHandle();return;}const rel=objectPair();if(!rel){host.hidden=true;host.innerHTML='';return;}host.hidden=false;host.innerHTML=spaceHtml(rel);}
function syncLayerObject(layer){const obj=findCanvasObject(layer.id);if(!obj||obj.group)return;obj.set({left:(obj.side||0)*pageWidth()+layer.box.x+layer.box.w/2,top:layer.box.y+layer.box.h/2,dirty:true});obj.setCoords();}
function restorePairSelection(){const targets=selected.map(id=>findCanvasObject(id)).filter(o=>o&&o.selectable);changing=true;if(targets.length===1)canvas.setActiveObject(targets[0]);else if(targets.length>1)canvas.setActiveObject(new fabric.ActiveSelection(targets,{canvas}));changing=false;canvas.requestRenderAll();}
function bindSpaceUi(){const host=$('#space-ui');if(!host)return;host.addEventListener('pointerdown',e=>{const hit=e.target.closest('.gap-hit');if(!hit||spaceDrag)return;const rel=objectPair();if(!rel)return;e.preventDefault();e.stopPropagation();let mover=rel.mover.layer,direction=1;if(mover.locked&&!rel.anchor.layer.locked){mover=rel.anchor.layer;direction=-1;}if(mover.locked)return;spaceDrag={axis:rel.axis,x:e.clientX,y:e.clientY,startGap:rel.gap,mover,direction,startPos:mover.box[rel.axis==='x'?'x':'y'],startDoc:clone(doc),moved:false,engaged:false};hit.classList.add('dragging');try{hit.setPointerCapture(e.pointerId);}catch(err){}document.body.style.cursor=rel.axis==='x'?'ew-resize':'ns-resize';});host.addEventListener('pointermove',e=>{if(!spaceDrag)return;if(!spaceDrag.engaged){if(Math.hypot(e.clientX-spaceDrag.x,e.clientY-spaceDrag.y)<2)return;changing=true;canvas.discardActiveObject();spaceDrag.engaged=true;}const zoom=canvas.getZoom()||1,delta=(spaceDrag.axis==='x'?e.clientX-spaceDrag.x:e.clientY-spaceDrag.y)/zoom,key=spaceDrag.axis==='x'?'x':'y',size=spaceDrag.axis==='x'?'w':'h',limit=spaceDrag.axis==='x'?pageWidth():pageHeight();let pos=clamp(spaceDrag.startPos+spaceDrag.direction*delta,0,Math.max(0,limit-spaceDrag.mover.box[size]));pos=round(pos);if(pos!==spaceDrag.mover.box[key]){spaceDrag.mover.box[key]=pos;spaceDrag.moved=true;syncLayerObject(spaceDrag.mover);canvas.requestRenderAll();}moveSpaceHandle();});const endSpace=()=>{if(!spaceDrag)return;const drag=spaceDrag;spaceDrag=null;document.body.style.cursor='';changing=false;if(drag.moved){history.push(drag.startDoc);if(history.length>60)history.shift();future=[];markDirty();render();}else if(drag.engaged){restorePairSelection();placeCollageUi();}else placeSpaceUi();};host.addEventListener('pointerup',endSpace);host.addEventListener('pointercancel',endSpace);}
bindSpaceUi();
$('#space-ui').addEventListener('keydown',e=>{const hit=e.target.closest('[role="slider"]');if(!hit)return;const axis=hit.classList.contains('x')?'x':'y',positive=axis==='x'?'ArrowRight':'ArrowDown',negative=axis==='x'?'ArrowLeft':'ArrowUp';if(e.key!==positive&&e.key!==negative)return;e.preventDefault();e.stopPropagation();const rel=objectPair(axis);if(!rel)return;let mover=rel.mover.layer,direction=1;if(mover.locked&&!rel.anchor.layer.locked){mover=rel.anchor.layer;direction=-1;}if(mover.locked)return;const key=axis==='x'?'x':'y',size=axis==='x'?'w':'h',limit=axis==='x'?pageWidth():pageHeight(),step=(e.shiftKey?10:1)*(e.key===positive?1:-1),next=round(clamp(mover.box[key]+direction*step,0,Math.max(0,limit-mover.box[size])));if(next===mover.box[key])return;const before=clone(doc);changing=true;canvas.discardActiveObject();mover.box[key]=next;syncLayerObject(mover);restorePairSelection();changing=false;history.push(before);if(history.length>60)history.shift();future=[];markDirty();renderInspector();placeCollageUi();$('#space-ui [role="slider"]')?.focus();});
const drawTools=new Set(['text','photo','shape','collage','grid']);
function dragBox(x1,y1,x2,y2,type,shift){const side=x1>=pageWidth()?1:0;x2=clamp(x2,side*pageWidth(),side*pageWidth()+pageWidth());y2=clamp(y2,0,pageHeight());let x=Math.min(x1,x2),y=Math.min(y1,y2),w=Math.abs(x2-x1),h=Math.abs(y2-y1);if(type==='line'){if(Math.abs(x2-x1)>=Math.abs(y2-y1)){x=Math.min(x1,x2);y=y1-.5;w=Math.abs(x2-x1);h=1;}else{x=x1-.5;y=Math.min(y1,y2);w=1;h=Math.abs(y2-y1);}}else if(type==='svg'&&pendingSvg&&!shift){const aspect=pendingSvg.aspect||1;if(w<h*aspect)w=h*aspect;else h=w/aspect;x=x2<x1?x1-w:x1;y=y2<y1?y1-h:y1;}else if(shift){const size=Math.max(w,h);w=h=size;x=x2<x1?x1-size:x1;y=y2<y1?y1-size:y1;}x-=side*pageWidth();x=clamp(x,0,pageWidth());y=clamp(y,0,pageHeight());w=clamp(w,0,pageWidth()-x);h=clamp(h,0,pageHeight()-y);return {x,y,w,h};}
function cancelDraw(){draw=null;if(rubber){canvas.remove(rubber);rubber=null;canvas.requestRenderAll();}}
canvas.on('mouse:down',opt=>{const e=opt.e;if(space||tool==='hand'){pan={x:e.clientX,y:e.clientY};canvas.selection=false;return;}if(preview||draw)return;const point=canvas.getScenePoint(e);if(point.x<0||point.x>(2*pageWidth())||point.y<0||point.y>pageHeight())return;view.side=point.x>=pageWidth()?1:0;if(drawTools.has(tool)){const type=tool==='shape'?shapeKind:tool;if(type==='svg'&&!pendingSvg){pickSvg();return;}draw={type,x:point.x,y:point.y,box:dragBox(point.x,point.y,point.x,point.y,type,e.shiftKey)};rubber=new fabric.Rect({left:point.x,top:point.y,width:.4,height:.4,fill:'rgba(119,18,179,.08)',stroke:'#7712b3',strokeWidth:.35,strokeDashArray:[1.4,1],selectable:false,evented:false,objectCaching:false,rx:type==='ellipse'?20:0,ry:type==='ellipse'?20:0});canvas.add(rubber);return;}if(tool!=='select')return;if(opt.target?.masterId&&inspectorTab!=='design'){inspectorTab='design';if(selected.includes(opt.target.masterId))renderInspector();}press={x:e.clientX,y:e.clientY,id:opt.target?.masterId||'',at:performance.now()};if(!opt.target?.masterId&&!(opt.target instanceof fabric.ActiveSelection)){selected=[];focusCell=null;renderInspector();}});
canvas.on('mouse:move',opt=>{if(pan){const v=canvas.viewportTransform;v[4]+=opt.e.clientX-pan.x;v[5]+=opt.e.clientY-pan.y;pan={x:opt.e.clientX,y:opt.e.clientY};syncSelectionCoords();canvas.requestRenderAll();placeCollageUi();placePhotoCropUi();return;}if(!draw||!rubber){hoverCollageCell(opt);return;}const point=canvas.getScenePoint(opt.e);draw.box=dragBox(draw.x,draw.y,point.x,point.y,draw.type,opt.e.shiftKey);const side=draw.x>=pageWidth()?1:0;rubber.set({left:side*pageWidth()+draw.box.x,top:draw.box.y,width:Math.max(draw.box.w,.4),height:Math.max(draw.box.h,.4),rx:draw.type==='ellipse'?Math.max(draw.box.w,.4)/2:0,ry:draw.type==='ellipse'?Math.max(draw.box.h,.4)/2:0});rubber.setCoords();canvas.requestRenderAll();});
canvas.on('mouse:up',opt=>{clearGuides();if(draw){const d=draw;cancelDraw();const dragged=d.type==='line'?Math.max(d.box.w,d.box.h)>=3:d.box.w>=3&&d.box.h>=3;let box=d.box;if(!dragged){const preset={text:[72,18],photo:[72,96],rect:[56,40],ellipse:[48,48],line:[70,1],collage:[140,100],grid:[170,200],svg:[46,46]};let [w,h]=preset[d.type]||[60,40];if(d.type==='svg'&&pendingSvg){const aspect=pendingSvg.aspect||1;w=46;h=46/aspect;if(h>72){h=72;w=72*aspect;}if(w>90){w=90;h=90/aspect;}}const x=clamp(d.x-(d.x>=pageWidth()?pageWidth():0),0,pageWidth()-w),y=clamp(d.y,0,pageHeight()-h);box={x,y,w,h};}else if(opt.e.shiftKey&&d.type==='svg')box.free=true;addLayer(d.type,box);return;}if(pan){pan=null;canvas.setViewportTransform(canvas.viewportTransform);syncSelectionCoords();canvas.selection=!preview&&tool==='select';placeCollageUi();return;}if(tool==='select'&&press&&selectedAt<press.at&&Math.hypot(opt.e.clientX-press.x,opt.e.clientY-press.y)<5&&opt.target?.masterId&&selected.length===1&&selected[0]===opt.target.masterId){const l=allLayers().find(i=>i.id===opt.target.masterId);if(l?.type==='collage'&&!opt.e.shiftKey&&!l.angle){const id=collageHit(l,canvas.getScenePoint(opt.e))?.cell.id||null;if(id!==focusCell){focusCell=id;cellMenu=null;renderInspector();}}}clearGuides();placeCollageUi();press=null;});
canvas.on('mouse:dblclick',opt=>{const layer=allLayers().find(l=>l.id===opt.target?.masterId);if(layer?.type==='photo'&&layer.source==='custom'&&layer.dataUrl){opt.e.preventDefault();startPhotoCrop(layer);return;}if(layer?.type==='collage'&&activeCollage()===layer){const f=collageHit(layer,canvas.getScenePoint(opt.e));if(!f)return;if(f.cell.id!==focusCell){focusCell=f.cell.id;cellMenu=null;renderInspector();placeCollageUi();}if(f.cell.source==='custom'&&f.cell.dataUrl){opt.e.preventDefault();startPhotoCrop(layer,f.cell.id);}}});
canvas.on('mouse:wheel',opt=>{const e=opt.e;e.preventDefault();e.stopPropagation();if(e.ctrlKey||e.metaKey){const zoom=clamp(canvas.getZoom()*Math.pow(.999,e.deltaY),.2,8);canvas.zoomToPoint(new fabric.Point(e.offsetX,e.offsetY),zoom);zoomMode=zoom/2;updateZoomControls();}else{const v=canvas.viewportTransform;v[4]-=e.deltaX;v[5]-=e.deltaY;canvas.requestRenderAll();}syncSelectionCoords();if(snapMarks.length)renderGuides();placeCollageUi();placePhotoCropUi();});
